\label{thm:attainment}
Let $r\ge3$. The following statements hold.
\begin{enumerate}
\item If $\mathcal F$ is a family of $r$-graphs with $\pi_{r-2}(\mathcal F)<4r^{-r}$, then there is a finite $\mathcal F$-deficient $r$-palette $P$ with $\pi_{r-2}(\mathcal F)=\lambda(P)$.
\item We have $\Pi_{\mathrm u,\infty}^{(r)}\cap[0,4r^{-r}]=\Pi_{\mathrm u,\mathrm{fin}}^{(r)}\cap[0,4r^{-r}]=\mathcal D_r\cap[0,4r^{-r}]$, and this common set is countable and consists of algebraic numbers.
\end{enumerate}

\label{thm:nonclosed}
The following statements hold.
\begin{enumerate}
\item For all sufficiently large $r$, $\overline{\Pi_{\mathrm u,\infty}^{(r)}}=\overline{\mathcal D_r}=\{0\}\cup[r^{-r},1]$, and $\Pi_{\mathrm u,\infty}^{(r)}\cap[r^{-r},4r^{-r})$ is countable and dense in that interval.
\item For every $r\ge3$, the set $\Pi_{\mathrm u,\infty}^{(r)}$ contains no nondegenerate interval contained in $[0,4r^{-r})$.
\item For every $r\ge3$, $\left|\left(\overline{\Pi_{\mathrm u,\infty}^{(r)}}\setminus\Pi_{\mathrm u,\infty}^{(r)}\right)\cap[\frac{54}{25}r^{-r},\frac{9}{4}r^{-r}]\right|=2^{\aleph_0}$. In particular, $\Pi_{\mathrm u,\infty}^{(r)}$ is not closed.
\end{enumerate}

\label{thm:palette-tools}
The following statements hold.
\begin{enumerate}
\item For any family $\mathcal F$ of $r$-graphs, $\pi_{r-2}(\mathcal F)=\sup\{\lambda(P)\colon P\text{ is a finite }\mathcal F\text{-deficient }r\text{-palette}\}$.
\item For finite $r$-palettes $P,Q$, there is an $r$-graph in $\operatorname{Col}(P)\setminus\operatorname{Col}(Q)$ if and only if neither $P\to Q$ nor $P\to\operatorname{rev}(Q)$.
\end{enumerate}

For a finite palette $P$, let $\mathcal F_P$ consist of all finite $r$-graphs outside $\operatorname{Col}(P)$. The palette $P$ is $\mathcal F_P$-deficient. If $Q$ is also $\mathcal F_P$-deficient, then $\operatorname{Col}(Q)\subseteq\operatorname{Col}(P)$, since any $Q$-colorable $r$-graph outside $\operatorname{Col}(P)$ would belong to $\mathcal F_P$. Hence \cref{thm:palette-tools}(ii) gives $Q\to P$ or $Q\to\operatorname{rev}(P)$, so $\lambda(Q)\le\lambda(P)$. \Cref{thm:palette-tools}(i) proves $\pi_{r-2}(\mathcal F_P)=\lambda(P)$.

To prove the second inclusion, suppose that $P\ne\varnothing$ and choose a tuple whose distinct colors have multiplicities $a_1,\ldots,a_t$. The polynomial $\Lambda_P$ is at least the corresponding monomial. Maximizing that monomial gives
\begin{equation}\label{eq:single-tuple}
\lambda(P)\ge\prod_{i=1}^t\left(\frac{a_i}{r}\right)^{a_i}
=r^{-r}\prod_{i=1}^ta_i^{a_i}\ge r^{-r}.
\end{equation}
Since $P\subseteq C(P)^r$, we have $\Lambda_P(\boldsymbol x)\le(\sum_{c\in C(P)}x_c)^r=1$ for every $\boldsymbol x\in\mathbb{S}_{C(P)}$, so $\lambda(P)\le1$. Thus every finite palette has Lagrangian either zero or in $[r^{-r},1]$. By \cref{thm:palette-tools}(i), $\pi_{r-2}(\mathcal F)$ is the supremum of the Lagrangians of finite $\mathcal F$-deficient palettes. If this supremum is positive, at least one such palette has positive Lagrangian, and hence $r^{-r}\le\pi_{r-2}(\mathcal F)\le1$.

\label{lem:orientation-lift}
The following statements hold.
\begin{enumerate}[beginpenalty=10000]
\item If $H$ is a finite simple $k$-graph and $1\le m\le k!$, selecting exactly $m$ permutations of each edge gives a $k$-palette $P_m(H)$ with $\lambda(P_m(H))=\frac{m}{k!}\lambda(H)$.
\item If $r\ge k\ge3$ and $P$ is a finite $k$-palette, then $\lambda(\operatorname{lift}_r(P))=\frac{k^k}{r^r}\lambda(P)$. The lifting operation preserves palette homomorphisms.
\end{enumerate}

\label{def:ladder}
An \emph{$m$-ladder} in a simple $r$-graph $H$ consists of distinct vertices $b_1,\ldots,b_m$ and $(r-2)$-sets $A_1,\ldots,A_{m-1}$ such that $A_i\cap\{b_i,b_{i+1},\ldots,b_m\}=\varnothing$ for every $i\in[m-1]$ and $A_i\cup\{b_i,b_j\}\in H$ for every $1\le i<j\le m$. The sets $A_i$ may intersect one another and may contain earlier vertices $b_j$ with $j<i$. We call the vertices $b_i$ the \emph{spine vertices} and the sets $A_i$ the \emph{cores}.
A rainbow palette contains an $m$-ladder if its underlying hypergraph does.

\label{prop:exact-reader}
For every sufficiently large $n\in18\mathbb N$ with $n\ge36(q+1)$, there is a continuous function $\Psi_n\colon[0,\infty)\to[0,\infty)$, strictly increasing on $(0,\infty)$, such that the following hold for every finite $3$-palette $P$ with $P\ne\varnothing$ equipped with a homomorphism $\theta\colon P\to P_*$.
\begin{enumerate}
\item Every optimal weighting of $\mathcal H_{n,P}$ is constant within each auxiliary class, that is, $a_i=A/n$ and $b_i=B/n$ for all $i$.
\item We have $\lambda(\mathcal H_{n,P})=\Psi_n(\lambda(P))$; in particular, this value is independent of the choice of $\theta$.
\item We have $\lambda(\mathcal H_{n,P})=12^{-12}(4+\lambda(P)n^{-8})+O(n^{-12})$, where the error is nonnegative and the implicit constant is uniform over these choices of $P$ and $\theta$.
\end{enumerate}

\label{lem:connectors}
The following statements hold.
\begin{enumerate}
\item The $\mathcal M_j$ are pairwise edge-disjoint simple $9$-graphs. The $9$-graph $\bigcup_{j=0}^{q-1}\mathcal M_j$ is $9$-partite, and $\sum_{j=0}^{q-1}R_j\le(S/9)^9$.
\item Every $A$-color has degree 5 and every $B$-color degree 4 in each $\mathcal M_j$. At the weighting $a_i=A/n$, $b_i=B/n$, we have $R_j=A^5B^4/n^8$, $\partial_{a_i}R_j=5(A/n)^4(B/n)^4$, and $\partial_{b_i}R_j=4(A/n)^5(B/n)^3$.
\item If $\Delta\ge h^3/28$, then $R_j\le\frac{1675}{1728}A^4B^2\Delta$.
\end{enumerate}

\label{lem:finite-products}
The two products satisfy $\lambda(P\star Q)=\frac{k^ks^s}{(k+s)^{k+s}}\lambda(P)\lambda(Q)$ and $\lambda(P\diamond Q)=\lambda(P)\lambda(Q)$.
If $P'\to P$ and $Q'\to Q$, with $P'$ a $k$-palette and $Q'$ an $s$-palette on disjoint color sets, then $P'\star Q'\to P\star Q$ and $P'\diamond Q'\to P\diamond Q$.

\label{cl:app-fr-minimal}
The following statements hold.
\begin{enumerate}
\item Every endomorphism of $P$ is an automorphism, and $P\to\operatorname{rev}(P)$ implies $P\cong\operatorname{rev}(P)$.
\item For each $i\ne j$, there is a tuple in $P$ and a position occupied by $i$ such that replacing that occurrence of $i$ by $j$ gives a tuple outside $P$.
\item There are $\beta,\varepsilon_0>0$ such that $y_i\ge\beta$ for every $i\in[m]$ whenever $\boldsymbol y\in\mathbb{S}_m$ and $\Lambda_P(\boldsymbol y)\ge\lambda(P)-\varepsilon_0$.
\end{enumerate}

\label{prop:app-fr-consequences}
The following statements hold.
\begin{enumerate}
\item Let $Q\in\mathcal C_k(P)$ and let $\boldsymbol x\in\mathbb{S}_{C(Q)}$ satisfy $\Lambda_Q(\boldsymbol x)\ge\lambda(P)-\delta/2$. There are $P'\in\{P,\operatorname{rev}(P)\}$ and nonnegative numbers $z_{v,i}$, with $\sum_{i\in[m]}z_{v,i}=x_v$ for each $v\in C(Q)$, such that
\begin{equation}\label{eq:app-fr-split}
 \sum_{\substack{\boldsymbol v\in C(Q)^r\\\boldsymbol i\in[m]^r}}
 \left|\mathbf1_{\{\boldsymbol v\in Q\}}-\mathbf1_{\{\boldsymbol i\in P'\}}\right|
 \prod_{a\in[r]}z_{v_a,i_a}
 \le\frac53\bigl(\lambda(P)-\Lambda_Q(\boldsymbol x)\bigr).
\end{equation}
\item Let $Q\in\mathcal C_k(P)$ satisfy $\lambda(Q)=\lambda(P)$, and let $\boldsymbol x$ be an optimal weighting with support $J$. Then $Q[J]$ is a complete blowup of $P$ or $\operatorname{rev}(P)$, with all $m$ parts nonempty. If $\boldsymbol x$ has minimum support among all optimal weightings of $Q$, then $Q[J]$ is isomorphic to $P$ or $\operatorname{rev}(P)$, and $|J|=m$.
\item For every sufficiently large $n$, every palette maximizing the number of admissible tuples among all $n$-color $\mathcal G$-deficient palettes is a complete blowup of $P$ or $\operatorname{rev}(P)$.
\end{enumerate}

\label{prop:countable-colorability}
The following statements hold.
\begin{enumerate}
\item For every $m\ge3$, we have $\lambda(P_m)=\lambda(P)=2/9$.
\item Every finite $3$-graph is $P$-colorable, but for each fixed $m\ge3$, all sufficiently large complete $3$-graphs fail to be $P_m$-colorable.
\end{enumerate}
